import Database from "better-sqlite3";
import path from "path";

const DB_PATH = "/home/user/qwik-app/db.sqlite";

let db: Database.Database | null = null;

export function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH);
    db.pragma("journal_mode = WAL");
    db.pragma("foreign_keys = ON");
    initializeDb(db);
  }
  return db;
}

function initializeDb(db: Database.Database): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS Product (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      price REAL NOT NULL
    );

    CREATE TABLE IF NOT EXISTS Coupon (
      code TEXT PRIMARY KEY,
      type TEXT NOT NULL CHECK(type IN ('PERCENT', 'FIXED', 'BOGO')),
      value REAL NOT NULL,
      minSpend REAL NOT NULL
    );

    CREATE TABLE IF NOT EXISTS CartItem (
      productId INTEGER PRIMARY KEY,
      quantity INTEGER NOT NULL,
      FOREIGN KEY(productId) REFERENCES Product(id)
    );

    CREATE TABLE IF NOT EXISTS ActiveCoupon (
      code TEXT PRIMARY KEY,
      FOREIGN KEY(code) REFERENCES Coupon(code)
    );
  `);

  // Seed data: only insert if tables are empty
  const productCount = db.prepare("SELECT COUNT(*) as count FROM Product").get() as { count: number };
  if (productCount.count === 0) {
    const insertProduct = db.prepare("INSERT INTO Product (name, price) VALUES (?, ?)");
    insertProduct.run("Widget A", 10.0);
    insertProduct.run("Widget B", 25.0);
    insertProduct.run("Widget C", 50.0);
    insertProduct.run("Widget D", 100.0);
  }

  const couponCount = db.prepare("SELECT COUNT(*) as count FROM Coupon").get() as { count: number };
  if (couponCount.count === 0) {
    const insertCoupon = db.prepare("INSERT INTO Coupon (code, type, value, minSpend) VALUES (?, ?, ?, ?)");
    insertCoupon.run("SAVE10", "PERCENT", 10.0, 25.0);
    insertCoupon.run("FLAT5", "FIXED", 5.0, 20.0);
    insertCoupon.run("BOGO2", "BOGO", 2.0, 30.0);
    insertCoupon.run("BOGO1", "BOGO", 1.0, 15.0);
    insertCoupon.run("SAVE50", "PERCENT", 50.0, 100.0);
    insertCoupon.run("FLAT50", "FIXED", 50.0, 50.0);
  }
}

import { getDb } from "./db";

export interface CartItem {
  productId: number;
  name: string;
  price: number;
  quantity: number;
  total: number;
}

export interface CouponInfo {
  code: string;
  type: "PERCENT" | "FIXED" | "BOGO";
  value: number;
  minSpend: number;
}

export interface CartState {
  items: CartItem[];
  subtotal: number;
  coupon: CouponInfo | null;
  discount: number;
  total: number;
  error: string | null;
}

export function getCartState(): CartState {
  const db = getDb();

  // Get cart items with product info, sorted by productId ascending
  const items = db
    .prepare(
      `SELECT c.productId, p.name, p.price, c.quantity
       FROM CartItem c
       JOIN Product p ON c.productId = p.id
       ORDER BY c.productId ASC`
    )
    .all() as Array<{ productId: number; name: string; price: number; quantity: number }>;

  const cartItems: CartItem[] = items.map((item) => ({
    productId: item.productId,
    name: item.name,
    price: item.price,
    quantity: item.quantity,
    total: Math.round(item.price * item.quantity * 100) / 100,
  }));

  const subtotal = Math.round(cartItems.reduce((sum, item) => sum + item.total, 0) * 100) / 100;

  // Get active coupon
  const activeCouponRow = db
    .prepare(
      `SELECT c.code, c.type, c.value, c.minSpend
       FROM ActiveCoupon a
       JOIN Coupon c ON a.code = c.code`
    )
    .get() as { code: string; type: string; value: number; minSpend: number } | undefined;

  let coupon: CouponInfo | null = null;
  let discount = 0;
  let error: string | null = null;

  if (activeCouponRow) {
    // Check minSpend
    if (subtotal < activeCouponRow.minSpend) {
      // Remove the active coupon since minSpend is no longer met
      db.prepare("DELETE FROM ActiveCoupon").run();
      error = "Minimum spend not met";
    } else {
      coupon = {
        code: activeCouponRow.code,
        type: activeCouponRow.type as "PERCENT" | "FIXED" | "BOGO",
        value: activeCouponRow.value,
        minSpend: activeCouponRow.minSpend,
      };
      discount = calculateDiscount(coupon, cartItems, subtotal);
    }
  }

  let total = Math.round((subtotal - discount) * 100) / 100;
  if (total < 0) total = 0;

  return {
    items: cartItems,
    subtotal,
    coupon,
    discount,
    total,
    error,
  };
}

function calculateDiscount(
  coupon: CouponInfo,
  items: CartItem[],
  subtotal: number
): number {
  switch (coupon.type) {
    case "PERCENT": {
      return Math.round(subtotal * (coupon.value / 100) * 100) / 100;
    }
    case "FIXED": {
      const discount = coupon.value;
      return Math.min(discount, subtotal); // cannot exceed subtotal
    }
    case "BOGO": {
      const targetProductId = coupon.value; // value stores the productId as a float
      const cartItem = items.find((item) => item.productId === targetProductId);
      if (!cartItem) return 0;
      const freeUnits = Math.floor(cartItem.quantity / 2);
      return Math.round(freeUnits * cartItem.price * 100) / 100;
    }
    default:
      return 0;
  }
}

export function updateCartItem(productId: number, quantity: number): CartState {
  const db = getDb();

  // Validate product exists
  const product = db.prepare("SELECT id FROM Product WHERE id = ?").get(productId);
  if (!product) {
    return getCartState();
  }

  if (quantity <= 0) {
    db.prepare("DELETE FROM CartItem WHERE productId = ?").run(productId);
  } else {
    db.prepare(
      "INSERT INTO CartItem (productId, quantity) VALUES (?, ?) ON CONFLICT(productId) DO UPDATE SET quantity = ?"
    ).run(productId, quantity, quantity);
  }

  // After cart modification, check if active coupon still meets minSpend
  return getCartState();
}

export function applyCoupon(code: string): CartState {
  const db = getDb();

  // Check if coupon exists
  const couponRow = db.prepare("SELECT code, type, value, minSpend FROM Coupon WHERE code = ?").get(code) as
    | { code: string; type: string; value: number; minSpend: number }
    | undefined;

  if (!couponRow) {
    // Clear any existing active coupon
    db.prepare("DELETE FROM ActiveCoupon").run();
    const state = getCartState();
    state.error = "Invalid coupon code";
    state.coupon = null;
    state.discount = 0;
    state.total = state.subtotal;
    return state;
  }

  // Check minSpend
  const cartItems = getCartItemsRaw();
  const subtotal = Math.round(cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0) * 100) / 100;

  if (subtotal < couponRow.minSpend) {
    // Don't apply the coupon
    db.prepare("DELETE FROM ActiveCoupon").run();
    const state = getCartState();
    state.error = "Minimum spend not met";
    state.coupon = null;
    state.discount = 0;
    state.total = state.subtotal;
    return state;
  }

  // Apply the coupon (clear existing first since only one active)
  db.prepare("DELETE FROM ActiveCoupon").run();
  db.prepare("INSERT INTO ActiveCoupon (code) VALUES (?)").run(code);

  return getCartState();
}

function getCartItemsRaw(): Array<{ productId: number; price: number; quantity: number }> {
  const db = getDb();
  return db
    .prepare(
      `SELECT c.productId, p.price, c.quantity
       FROM CartItem c
       JOIN Product p ON c.productId = p.id`
    )
    .all() as Array<{ productId: number; price: number; quantity: number }>;
}

export function clearCart(): CartState {
  const db = getDb();
  db.prepare("DELETE FROM CartItem").run();
  db.prepare("DELETE FROM ActiveCoupon").run();
  return getCartState();
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { getCartState, updateCartItem, applyCoupon, clearCart } from "~/lib/cart";

export const onGet: RequestHandler = async ({ json }) => {
  const state = getCartState();
  json(200, state);
};

export const onPost: RequestHandler = async ({ request, json }) => {
  try {
    const body = await request.json();
    const { action } = body as { action: string; productId?: number; quantity?: number; code?: string };

    let state;

    switch (action) {
      case "update": {
        const productId = (body as { productId: number }).productId;
        const quantity = (body as { quantity: number }).quantity;
        if (productId === undefined || quantity === undefined) {
          json(400, { error: "Missing productId or quantity" });
          return;
        }
        state = updateCartItem(productId, quantity);
        break;
      }
      case "applyCoupon": {
        const code = (body as { code: string }).code;
        if (!code) {
          json(400, { error: "Missing coupon code" });
          return;
        }
        state = applyCoupon(code);
        break;
      }
      case "clear": {
        state = clearCart();
        break;
      }
      default: {
        json(400, { error: "Invalid action" });
        return;
      }
    }

    json(200, state);
  } catch (e) {
    json(400, { error: "Invalid request body" });
  }
};

import { component$, useSignal, useTask$ } from "@builder.io/qwik";
import { routeLoader$, routeAction$, Form, useLocation } from "@builder.io/qwik-city";
import type { CartState } from "~/lib/cart";
import { getCartState, updateCartItem, applyCoupon, clearCart } from "~/lib/cart";

export const useCartLoader = routeLoader$<CartState>(() => {
  return getCartState();
});

export const useUpdateItem = routeAction$((data) => {
  const productId = parseInt(data.get("productId") as string, 10);
  const quantity = parseInt(data.get("quantity") as string, 10);
  return updateCartItem(productId, quantity);
});

export const useApplyCoupon = routeAction$((data) => {
  const code = data.get("code") as string;
  return applyCoupon(code);
});

export const useClearCart = routeAction$(() => {
  return clearCart();
});

export default component$(() => {
  const cartSignal = useCartLoader();
  const updateAction = useUpdateItem();
  const applyAction = useApplyCoupon();
  const clearAction = useClearCart();
  const couponCode = useSignal("");

  return (
    <div class="cart-container">
      <h1>Shopping Cart</h1>

      {cartSignal.value.error && (
        <div class="error-message">{cartSignal.value.error}</div>
      )}

      {cartSignal.value.items.length === 0 ? (
        <p class="empty-cart">Your cart is empty.</p>
      ) : (
        <table class="cart-table">
          <thead>
            <tr>
              <th>Product</th>
              <th>Price</th>
              <th>Quantity</th>
              <th>Total</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {cartSignal.value.items.map((item) => (
              <tr key={item.productId}>
                <td>{item.name}</td>
                <td>${item.price.toFixed(2)}</td>
                <td>{item.quantity}</td>
                <td>${item.total.toFixed(2)}</td>
                <td class="action-cell">
                  <Form action={updateAction} spaReset>
                    <input type="hidden" name="productId" value={item.productId} />
                    <div class="quantity-controls">
                      <button
                        type="submit"
                        name="quantity"
                        value={item.quantity - 1}
                        class="qty-btn"
                      >
                        -
                      </button>
                      <span class="qty-display">{item.quantity}</span>
                      <button
                        type="submit"
                        name="quantity"
                        value={item.quantity + 1}
                        class="qty-btn"
                      >
                        +
                      </button>
                    </div>
                  </Form>
                  <Form action={updateAction} spaReset>
                    <input type="hidden" name="productId" value={item.productId} />
                    <input type="hidden" name="quantity" value="0" />
                    <button type="submit" class="remove-btn">
                      Remove
                    </button>
                  </Form>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <div class="cart-summary">
        <div class="summary-row">
          <strong>Subtotal:</strong>
          <span>${cartSignal.value.subtotal.toFixed(2)}</span>
        </div>

        {cartSignal.value.coupon && (
          <div class="summary-row coupon-info">
            <strong>Coupon Applied:</strong>
            <span>
              {cartSignal.value.coupon.code} ({cartSignal.value.coupon.type})
            </span>
          </div>
        )}

        {cartSignal.value.discount > 0 && (
          <div class="summary-row discount-row">
            <strong>Discount:</strong>
            <span>-${cartSignal.value.discount.toFixed(2)}</span>
          </div>
        )}

        <div class="summary-row total-row">
          <strong>Total:</strong>
          <span>${cartSignal.value.total.toFixed(2)}</span>
        </div>
      </div>

      <div class="cart-actions">
        <Form action={applyCoupon} spaReset class="coupon-form">
          <input
            type="text"
            name="code"
            placeholder="Enter coupon code"
            value={couponCode.value}
            onInput$={(e) => (couponCode.value = (e.target as HTMLInputElement).value)}
            class="coupon-input"
          />
          <button type="submit" class="apply-btn">
            Apply Coupon
          </button>
        </Form>

        <Form action={clearAction} spaReset>
          <button type="submit" class="clear-btn">
            Clear Cart
          </button>
        </Form>
      </div>

      <style>{`
        .cart-container {
          max-width: 800px;
          margin: 0 auto;
          padding: 20px;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
        }

        h1 {
          margin-bottom: 20px;
          color: #333;
        }

        .error-message {
          background: #ffe0e0;
          color: #c00;
          padding: 12px 16px;
          border-radius: 6px;
          margin-bottom: 16px;
          border: 1px solid #f5c6cb;
        }

        .empty-cart {
          color: #888;
          font-style: italic;
          padding: 40px 0;
          text-align: center;
        }

        .cart-table {
          width: 100%;
          border-collapse: collapse;
          margin-bottom: 20px;
        }

        .cart-table th {
          background: #f8f9fa;
          padding: 12px 8px;
          text-align: left;
          border-bottom: 2px solid #dee2e6;
          color: #555;
          font-size: 14px;
        }

        .cart-table td {
          padding: 12px 8px;
          border-bottom: 1px solid #eee;
          vertical-align: middle;
        }

        .action-cell {
          display: flex;
          gap: 8px;
          align-items: center;
        }

        .quantity-controls {
          display: flex;
          align-items: center;
          gap: 4px;
        }

        .qty-btn {
          width: 30px;
          height: 30px;
          border: 1px solid #ccc;
          background: #fff;
          border-radius: 4px;
          cursor: pointer;
          font-size: 16px;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 0;
        }

        .qty-btn:hover {
          background: #f0f0f0;
        }

        .qty-display {
          min-width: 24px;
          text-align: center;
          font-weight: 500;
        }

        .remove-btn {
          padding: 4px 12px;
          border: 1px solid #dc3545;
          background: #fff;
          color: #dc3545;
          border-radius: 4px;
          cursor: pointer;
          font-size: 13px;
        }

        .remove-btn:hover {
          background: #dc3545;
          color: #fff;
        }

        .cart-summary {
          background: #f8f9fa;
          padding: 20px;
          border-radius: 8px;
          margin-bottom: 20px;
        }

        .summary-row {
          display: flex;
          justify-content: space-between;
          padding: 8px 0;
          font-size: 16px;
        }

        .coupon-info {
          color: #28a745;
        }

        .discount-row {
          color: #28a745;
        }

        .total-row {
          border-top: 2px solid #dee2e6;
          margin-top: 8px;
          padding-top: 12px;
          font-size: 20px;
          font-weight: 700;
        }

        .cart-actions {
          display: flex;
          gap: 16px;
          align-items: center;
          flex-wrap: wrap;
        }

        .coupon-form {
          display: flex;
          gap: 8px;
          align-items: center;
        }

        .coupon-input {
          padding: 8px 12px;
          border: 1px solid #ccc;
          border-radius: 4px;
          font-size: 14px;
          width: 200px;
        }

        .apply-btn {
          padding: 8px 16px;
